import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static void almostSorted(List<Integer> arr) {int n = arr.size();List<Integer> sorted = new ArrayList<>(arr);Collections.sort(sorted);List<Integer> diff = new ArrayList<>();for (int i = 0; i < n; i++) {if (!arr.get(i).equals(sorted.get(i))) {diff.add(i);}}if (diff.isEmpty()) {System.out.println("yes");return;}int l = diff.get(0);int r = diff.get(diff.size() - 1);List<Integer> swapped = new ArrayList<>(arr);Collections.swap(swapped, l, r);if (isSorted(swapped)) {System.out.println("yes");System.out.println("swap " + (l + 1) + " " + (r + 1));return;}List<Integer> reversed = new ArrayList<>(arr);reverse(reversed, l, r);if (isSorted(reversed)) {System.out.println("yes");System.out.println("reverse " + (l + 1) + " " + (r + 1));return;}System.out.println("no");}private static boolean isSorted(List<Integer> arr) {for (int i = 0; i < arr.size() - 1; i++) {if (arr.get(i) > arr.get(i + 1)) return false;}return true;}private static void reverse(List<Integer> arr, int l, int r) {while (l < r) {Collections.swap(arr, l, r);l++;r--;}}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());Result.almostSorted(arr);bufferedReader.close();}}